begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select plan(15);
set local timezone='UTC';
select has_function('public','apply_coach_action',array['uuid','uuid'],'reviewed action coordinator exists');
select ok(not has_function_privilege('anon','public.apply_coach_action(uuid,uuid)','EXECUTE'),'anonymous users cannot execute proposals');
select has_function('public','set_planner_task_completion',array['uuid','boolean','timestamp with time zone'],'task completion requires the reviewed version');
select ok(not has_table_privilege('authenticated','public.coach_actions','UPDATE'),'clients cannot author commands or receipts');
select ok(not has_function_privilege('authenticated','public.replace_coach_action(uuid,uuid,jsonb,boolean)','EXECUTE'),'clients cannot replace sealed actions');
select throws_ok('select public.apply_coach_action(gen_random_uuid(),gen_random_uuid())','42501','authentication_required','direct coordinator calls require identity');
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','coach-actions@example.com') on conflict do nothing;
insert into public.profiles(id,username,timezone,timezone_confirmed_at) values('11111111-1111-4111-8111-111111111111','coach_actions','UTC',now()) on conflict(id) do update set timezone='UTC',timezone_confirmed_at=now();
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
create temporary table task as select * from public.create_planner_task('Reviewed task',current_date);
create temporary table home as select public.ensure_coach_home('11111111-1111-4111-8111-111111111111') id;
select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'22222222-2222-4222-8222-222222222222','Move my task','{}',0,'turn');
select public.finish_coach_run('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','Review this move','{}',jsonb_build_array(jsonb_build_object('kind','task_move','title','Move reviewed task','command',jsonb_build_object('timezone','UTC','asOfDate',current_date,'taskId',(select task_id from task),'expectedUpdatedAt',(select updated_at from task),'date',current_date+1),'preview','{}'::jsonb)));
create temporary table action as select id,command from public.coach_actions where run_id='22222222-2222-4222-8222-222222222222';
create temporary table receipt as select public.apply_coach_action((select id from action),'33333333-3333-4333-8333-333333333333') result;
select throws_ok($$select public.set_planner_task_completion((select task_id from task),true,(select updated_at from task))$$,'P0001','task_stale','normal task completion rejects an outdated reviewed version');
select is((select result->>'kind' from receipt),'task_move','the reviewed task command applies');
select is((select scheduled_date from public.planner_tasks where id=(select task_id from task)),current_date+1,'canonical task date changes');
select is((select status from public.coach_actions where id=(select id from action)),'applied','domain change and proposal receipt commit together');
select is(public.apply_coach_action((select id from action),'44444444-4444-4444-8444-444444444444'),(select result from receipt),'repeated Apply returns the original receipt');
select public.set_planner_task_scheduled_date((select task_id from task),current_date+3,(select updated_at from public.planner_tasks where id=(select task_id from task)));
select public.apply_coach_action((select id from action),'33333333-3333-4333-8333-333333333333');
select is((select scheduled_date from public.planner_tasks where id=(select task_id from task)),current_date+3,'replaying a receipt never overwrites a later normal edit');
insert into public.coach_actions(id,owner_id,thread_id,run_id,kind,title,command,preview) select '55555555-5555-4555-8555-555555555555','11111111-1111-4111-8111-111111111111',(select id from home),'22222222-2222-4222-8222-222222222222','task_move','Stale move',command,'{}' from action;
select throws_ok($$select public.apply_coach_action('55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666')$$,'P0001','action_stale','stale task versions cannot overwrite a normal edit');
select ok(not exists(select 1 from public.coach_action_requests where request_id='66666666-6666-4666-8666-666666666666'),'failed changes do not create success receipts');
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',true);
select throws_ok($$select public.apply_coach_action((select id from action),gen_random_uuid())$$,'P0001','action_not_found','another owner cannot apply the proposal');
select * from finish();
rollback;
